"""Out-of-band state drift detector (Loop Engineering P4, epic #75).

The SessionStart hook emits `watchPaths` for `.synaptory/.orchestrator/
pipeline-state.json` and `.synaptory.yaml`; when either changes on disk the
`FileChanged` hook (synaptory-watch-drift.sh) runs this validator. It catches
the case where those files were edited OUTSIDE the tracker CLI / state
machines (a hand edit, a bad merge, a stray tool write) and left in a shape
the pipeline can't safely act on — before the orchestrator transitions
anything on top of the corruption.

Pure and file-only so it unit-tests against fixtures. The hook turns a
non-empty problem list into an `additionalContext` warning + a `watch_drift`
event; a clean file produces nothing (idempotent, cheap — FileChanged can
fire often).
"""

from __future__ import annotations

import json
import os
from pathlib import Path
from typing import Any

try:
    from story_pipeline import STORY_STATES
except Exception:  # pragma: no cover - defensive; keep the validator importable
    STORY_STATES = [
        "queued", "in_progress", "testing", "reviewing",
        "awaiting_acceptance", "done", "cancelled", "blocked",
    ]

_KNOWN_BUILD_MODES = {"scrum", "kanban", "spq"}


def _validate_substate(sub: dict[str, Any], label: str) -> list[str]:
    """Problems in one flat lifecycle sub-state (v2 top-level, or a v3 spec)."""
    problems: list[str] = []
    if "lifecycle_state" not in sub:
        problems.append(f"{label}: missing lifecycle_state")
    stories = sub.get("current_stories")
    if stories is not None and not isinstance(stories, list):
        problems.append(f"{label}: current_stories is not a list")
        return problems
    for i, s in enumerate(stories or []):
        if not isinstance(s, dict):
            problems.append(f"{label}: story #{i} is not an object")
            continue
        sid = s.get("id", f"#{i}")
        st = s.get("state")
        if st not in STORY_STATES:
            problems.append(
                f"{label}: story {sid} has unknown sub-state {st!r} "
                f"(valid: {', '.join(STORY_STATES)})"
            )
    return problems


def validate_pipeline_state(state: dict[str, Any]) -> list[str]:
    """Return a list of drift problems in a parsed pipeline-state dict; empty
    means clean. Handles both v2 (flat) and v3 (multi-spec) layouts."""
    if not isinstance(state, dict):
        return ["pipeline-state.json is not a JSON object"]

    problems: list[str] = []
    build_mode = state.get("build_mode")
    if build_mode not in _KNOWN_BUILD_MODES:
        problems.append(f"unknown build_mode {build_mode!r}")

    specs = state.get("specs")
    if isinstance(specs, dict):
        # v3 multi-spec: active_spec must resolve to an existing slot.
        active = state.get("active_spec")
        if active is not None and active not in specs:
            problems.append(
                f"active_spec {active!r} has no matching entry in specs "
                f"(have: {', '.join(specs) or 'none'})"
            )
        for sid, sub in specs.items():
            if isinstance(sub, dict):
                problems.extend(_validate_substate(sub, f"spec {sid}"))
            else:
                problems.append(f"spec {sid}: not an object")
    else:
        problems.extend(_validate_substate(state, "state"))
    return problems


def validate_config_text(text: str) -> list[str]:
    """Drift problems in `.synaptory.yaml` (the watched project config).

    Line-scan (no YAML dep, matching the other hook-layer readers): a
    top-level ``build_mode:`` must resolve to a known mode. Extend here as
    more config-drift classes matter. An absent key is fine (defaults apply).
    """
    problems: list[str] = []
    for raw in text.splitlines():
        line = raw.split("#", 1)[0].rstrip()
        if not line or line[0] in " \t":  # top-level keys only
            continue
        if line.startswith("build_mode:"):
            val = line.split(":", 1)[1].strip().strip('"').strip("'").lower()
            if val and val not in _KNOWN_BUILD_MODES:
                problems.append(
                    f".synaptory.yaml: unknown build_mode {val!r} "
                    f"(valid: {', '.join(sorted(_KNOWN_BUILD_MODES))})"
                )
    return problems


def check_drift(project_dir: str | os.PathLike[str]) -> dict[str, Any]:
    """Validate BOTH watched files — pipeline-state.json and .synaptory.yaml.

    Returns {"ok": bool, "problems": [...], "checked": bool}. A missing file
    is NOT drift (a fresh project has none) — it just isn't examined. A file
    that is present but corrupt / in a bad shape IS drift. Problems are
    prefixed with their source file so a combined report is unambiguous.
    """
    root = Path(project_dir)
    problems: list[str] = []
    checked = False

    state_path = root / ".synaptory" / ".orchestrator" / "pipeline-state.json"
    if state_path.exists():
        checked = True
        try:
            raw = state_path.read_text(encoding="utf-8")
        except OSError as exc:
            problems.append(f"cannot read pipeline-state.json: {exc}")
        else:
            if not raw.strip():
                # An empty file is truncation/corruption, not a fresh project.
                problems.append("pipeline-state.json is empty")
            else:
                try:
                    problems.extend(validate_pipeline_state(json.loads(raw)))
                except json.JSONDecodeError as exc:
                    problems.append(f"pipeline-state.json is not valid JSON: {exc}")

    cfg_path = root / ".synaptory.yaml"
    if cfg_path.exists():
        checked = True
        try:
            problems.extend(validate_config_text(cfg_path.read_text(encoding="utf-8")))
        except OSError as exc:
            problems.append(f"cannot read .synaptory.yaml: {exc}")

    return {"ok": not problems, "problems": problems, "checked": checked}


def main() -> int:
    """CLI: state_drift.py <project_dir> → JSON verdict on stdout, exit 0."""
    import sys

    project_dir = sys.argv[1] if len(sys.argv) > 1 else "."
    try:
        print(json.dumps(check_drift(project_dir)))
    except Exception as exc:  # never break the FileChanged hook
        print(json.dumps({"ok": True, "problems": [], "checked": False, "error": str(exc)}))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
